// Original supplementary lessons aligned to the user-supplied DATA6211/w outline.
export const dbUnits=[
 {id:1,title:'Database management systems',subtitle:'Understand why databases exist and who manages them.',chapter:'1',sessions:'DATA6211: 1-4. DATA6211w: 1.',overview:'Begin with the difference between raw facts and meaningful information. Compare a managed database with separate files, examine the people and components involved, and explain why good planning matters before a table is created.',themes:['The database management system (DBMS)','Database design and planning','The database administrator'],outcomes:['Differentiate between data and information.','Discuss the users of different database management systems.','Discuss the need for and potential costs of implementing a database system.','Discuss the advantages and disadvantages of a database approach.','Analyse the functional components of a DBMS.','Discuss the impact of a poorly designed database.','Discuss the main functions of a database administrator.'],check:'Explain who needs the data, how it becomes information, and what could fail if the database is badly designed.'},
 {id:2,title:'Data models and ER diagrams',subtitle:'Translate business rules into a picture of the data.',chapter:'2',sessions:'DATA6211: lab 5-10. DATA6211w: lab 2-3.',overview:'A model is a simplified description of the data a system must manage. Identify entities, attributes, relationships and constraints, read common ERD notation, and connect these ideas to relational databases and big data.',themes:['The necessity for data models','Entity relationship diagrams','The big data phenomenon'],outcomes:['Describe the basic building blocks of data models.','Discuss business rules and the purpose of data modelling.','Discuss the basic relational-model features from the user and designer perspectives.','Interpret entity relationship diagrams.','Identify different ERD notations.','Analyse relationships between tables.','Discuss how ERDs support a structured relational database design.','Explain the big data phenomenon.'],check:'Read an ERD in both directions, state minimum and maximum participation, and identify the rule behind each relationship.'},
 {id:3,title:'Relational design and keys',subtitle:'Identify rows and connect tables without unnecessary duplication.',chapter:'3',sessions:'DATA6211: theory 11-16. DATA6211w: theory 4.',overview:'Move from a conceptual model to relations, rows and columns. Select primary keys, distinguish search keys and foreign keys, recognise redundancy, and create or revise an ERD when a rule changes.',themes:['Elements and formation of relational database design','Working with ER diagrams'],outcomes:['Distinguish primary, secondary and foreign keys.','Discuss the significance of these keys in relational design.','Differentiate a database from a table.','Discuss data redundancy.','Create an entity relationship diagram.','Modify an entity relationship diagram.'],check:'For every table, justify its key and explain which foreign key implements each relationship.'},
 {id:4,title:'Developing and reviewing ER models',subtitle:'Use attributes, participation and relationship degree precisely.',chapter:'5',sessions:'DATA6211: theory 17-26. DATA6211w: theory 5-6.',overview:'Develop a complete model from a short scenario. Distinguish attribute types, optional participation and relationship degree. Resolve many-to-many relationships and review the design against real examples before implementation.',themes:['Characteristics of ER models','Developing ER diagrams','Degrees of entity relationships','Reviewing and revising ER diagrams'],outcomes:['Discuss the main characteristics of entity relationship models.','Apply business rules from descriptions of operations.','Analyse main entities and their relationships.','Develop implementable ERDs according to business rules.','Discuss attributes, primary keys and foreign keys.','Analyse unary, binary and ternary relationships.','Review and revise ER diagrams.'],check:'Test the diagram with normal, optional and exceptional cases. Every rule should have an explicit representation or a documented enforcement plan.'},
 {id:5,title:'Normalisation to 3NF',subtitle:'Use functional dependencies to improve table structure.',chapter:'7',sessions:'DATA6211: theory 27-34. DATA6211w: theory 7-8.',overview:'Normalisation reduces specific kinds of harmful duplication by decomposing relations using functional dependencies. Work from an unnormalised order record to 1NF, 2NF and 3NF, retaining the keys needed to reconstruct the information.',themes:['Introducing normalisation','Normalising up to third normal form (3NF)','Normalisation and database design'],outcomes:['Analyse the benefits of normalisation.','Use normalisation to produce normalised tables.','Normalise data up to third normal form.','Discuss why normalisation is needed in the design process.'],check:'State the candidate key and dependencies first. Show which dependency justifies every table split.'},
 {id:6,title:'SQL commands and queries',subtitle:'Create structures, change rows and retrieve useful information.',chapter:'8',sessions:'DATA6211: lab 35-48. DATA6211w: lab 9-12.',overview:'Use SQL to implement and query a relational model. Practise table constraints, data changes, views, indexes, filtering, joins, grouping and aggregate functions. Compare the documented syntax differences between the three database choices.',themes:['Basic SQL commands and functions','Querying a database using SQL'],outcomes:['Explain basic SQL commands and functions.','Create tables, indexes and views using SQL data definition commands.','Manipulate data using SQL data manipulation commands.','Write SQL queries to extract useful information.','Distinguish aggregate functions in SELECT statements.','Discuss the use of aggregate functions.'],check:'Run each query, explain every result column, and check how NULL, joins and grouping affect the rows counted.'}
];
const S=(heading,text)=>({heading,text});
const Q=(question,options,answer,explanation)=>({question,options,answer,explanation});
const L=(id,unit,title,sections,example,task,quizzes,diagram=null,sql=null)=>({id,unit,title,sections,example,task,quizzes,diagram,sql});
const T=(prompt,hint,solution)=>({prompt,hint,solution});
export const dbLessons=[
L('dbms',1,'Data, information and the DBMS',[
 S('Data becomes information','Data consists of recorded facts, such as individual marks, dates or item prices. Information is data interpreted in context for a purpose, such as the average mark for a particular class in a named assessment. A number alone does not tell us the unit, time period or meaning. Good information depends on accurate, relevant and sufficiently complete data.'),
 S('Database and DBMS','A database is an organised collection of related data. A database management system is software used to define, store, query, update and control access to that data. Microsoft SQL Server, PostgreSQL and MySQL are different relational DBMS products. A table is one structure inside a database, not the whole database. Applications communicate with a DBMS rather than each maintaining an unrelated copy of the same facts.'),
 S('Who uses the system?','End users view or enter information through an application. Developers build the application and its queries. Designers model the data and business rules. Analysts use data for reporting. Database administrators manage operational reliability and access. One person may perform several roles in a small organisation, but the responsibilities are still distinct.')],
 {title:'A class report',problem:'A lecturer records marks 50, 70 and 90 for one assessment. Identify the data, information and role of the DBMS.',solution:'Data: the three marks and the student and assessment identifiers attached to each. Information: the class average is (50 + 70 + 90) / 3 = 70. The DBMS stores valid records and runs the query; the lecturer interprets the average in context. Names, marks and assessment identity must be associated correctly.'},
 T('A shop records quantity 3 and unit price R25. Identify the raw data, useful information, and two different database users.','Explain a calculation and a decision it can support.','Data: item identity, quantity 3 and unit price R25. Information: this line has value R75. A cashier records a sale; a manager reviews sales totals. The DBMS stores and retrieves the linked facts.'),
 [Q('Which item is information?', ['An isolated number 70','A class average of 70% for a specified test','A column with no meaning'],1,'The average has context, units and a purpose.'),Q('Which is a DBMS?', ['A student row','PostgreSQL','A printed report'],1,'PostgreSQL is software that manages a database.')]),
L('dbms-components',1,'Benefits, costs and DBMS components',[
 S('Why move beyond separate files?','Separate spreadsheets can contain conflicting addresses or duplicated student records. A shared database can reduce uncontrolled duplication, provide consistent access and enforce common rules. Transactions help keep related updates together. Concurrency control coordinates simultaneous work. Central management does not guarantee correct design or correct input.'),
 S('Benefits and costs','Advantages can include controlled sharing, integrity constraints, access control, backup and recovery, and flexible querying. Costs include design effort, hardware or hosting, staff training, migration, administration and sometimes software licences. Free software still has operational costs. Centralisation can make an outage affect many users, so recovery and availability planning matter.'),
 S('Functional components','The query processor parses a statement and plans its execution. The storage manager handles physical data and indexes. The transaction and concurrency components coordinate changes. The recovery component uses logs and backups to restore consistency after failure. The authorisation system checks permissions. The catalogue stores metadata, such as table definitions and constraints. These are functional roles, not necessarily separate programs.')],
 {title:'A course enrolment transaction',problem:'A student enrols and the system reduces a seat count. What happens if the second update fails?',solution:'Both related changes should form one transaction. If the operation cannot complete, roll back the partial work. The transaction manager and recovery mechanisms protect consistency. Concurrency control must also prevent two users from claiming the last seat simultaneously.'},
 T('Give three benefits and three costs of replacing independent school spreadsheets with a DBMS. Explain why a backup alone does not prove recovery works.','Include people and process costs, not just software.','Benefits: shared consistent records, controlled access, enforceable data rules. Costs: migration and cleaning, training, ongoing hosting and administration. A backup may be incomplete or unusable; a restore test verifies that the backup and recovery process actually work.'),
 [Q('Which component chooses an execution plan?',['Query processor','Monitor screen','Primary key'],0,'The query processor analyses and plans queries.'),Q('A free DBMS has no costs.',['True','False'],1,'Hosting, administration, migration and training still have costs.')]),
L('planning-dba',1,'Planning, poor design and the DBA',[
 S('Plan from requirements','Identify the purpose, users, entities, rules, expected workload and reporting needs before creating tables. Gather examples and exceptional cases. Agree on access needs, retention, backup targets and recovery expectations. A design should support the actual operations, not only one convenient screen.'),
 S('What poor design causes','If course names are copied into every enrolment, a rename can leave conflicting names. If multiple phone numbers are packed into one field, searching and validation become difficult. Missing keys permit ambiguous duplicates. Poor relationships can lose information or produce misleading joins. Bad design can increase maintenance, errors and unnecessary cost.'),
 S('The database administrator','A DBA manages permissions, monitoring, backup and restoration, capacity, performance, configuration and operational changes. Least privilege gives each role only the access it needs. Backup schedules should match agreed recovery needs, and restores should be tested. A DBA works with developers and designers; operational tuning cannot repair every modelling mistake.')],
 {title:'Two addresses for one learner',problem:'A learner address is copied into 12 separate registration rows. Only 11 copies are updated after a move.',solution:'This is an update anomaly: rows disagree about one fact. Store the current learner address once in Learners, keyed by LearnerID, and refer to that learner from registration rows. If historical addresses are required, model address history explicitly rather than silently overwriting it.'},
 T('A school cannot restore its backup and all users can delete records. Identify two DBA responsibilities and one design-planning question.','Separate permissions, recovery and requirements.','Responsibilities: implement role-based least-privilege access and test backup restoration. Planning question: which records need audit/history retention, and who is authorised to change or remove them?'),
 [Q('Which is a DBA responsibility?',['Testing restoration','Choosing every student answer','Removing all constraints'],0,'Recovery must be planned and tested.'),Q('An update anomaly means:',['Related copies can disagree after a change','Every update is fast','The database has no tables'],0,'Duplicated facts can become inconsistent.')]),
L('models-rules',2,'Data models and business rules',[
 S('The model building blocks','An entity is a distinguishable type of thing about which data is stored, such as Student. An attribute describes it, such as StudentName. A relationship connects entity types, such as Student enrols in Course. A constraint limits valid data or associations. Entity instances are particular students or courses, not the entity types themselves.'),
 S('Business rules drive the model','A business rule states a meaningful requirement, such as each enrolment must belong to exactly one student. Determine minimum participation (zero or at least one) and maximum participation (one or many) in both directions. Avoid guessing from a single sample row. Ask whether a rule is permanent, optional or time-dependent.'),
 S('Different levels of a model','A conceptual model captures business meaning and entity relationships. A logical relational model specifies tables, attributes and keys without all storage decisions. A physical design adds implementation details such as DBMS data types and indexes. The end user sees useful records or views; the designer also sees keys, dependencies and constraints.')],
 {title:'Library borrowing rules',problem:'A member may borrow many book copies. A loan records one member and one copy. A copy may have many loans over time.',solution:'Model Member, BookCopy and Loan. Member to Loan is 1 to many, with a member allowed zero loans. Each loan refers to exactly one member. BookCopy to Loan is also 1 to many over time. The rule that a copy can have at most one active loan needs an additional temporal constraint; it is not expressed merely by a historical 1-to-many line.'},
 T('For an appointment system, identify three entities and two business rules. Distinguish an entity from an instance.','Consider Patient, Practitioner and Appointment.','Patient, Practitioner and Appointment are entity types. Patient 104 is an instance. Each appointment has one patient and one practitioner; a patient may have many appointments. Rules about overlapping bookings need additional validation.'),
 [Q('Which is an attribute?',['StudentName','Student enrols in Course','Each mark is between 0 and 100'],0,'StudentName describes a student.'),Q('Which should determine the model?',['Business requirements','A random table layout','Only the first row'],0,'Rules and required operations determine what must be represented.')]),
L('erd-reading',2,'Read relationships and ERD notation',[
 S('Read in both directions','Cardinality specifies allowed counts in a relationship. In a one-to-many relationship, one student can have many enrolments, but each enrolment belongs to one student. Optionality is the minimum count. A parent may have zero children even when each child must have a parent.'),
 S('Crow’s Foot, Chen and UML','Crow’s Foot diagrams show entities as boxes, with line-end symbols for one, many and optional participation. Chen notation commonly uses rectangles for entities, ovals for attributes and diamonds for relationships. UML class notation can show multiplicities such as 0..* or 1. Do not combine conventions without a legend. Our diagrams use labelled multiplicities and explicitly marked PK/FK attributes.'),
 S('Resolve many-to-many relationships','A student can take many courses and a course can have many students. In a relational implementation, introduce Enrolment with foreign keys to both Student and Course. Relationship attributes, such as Mark, belong in Enrolment. A unique student-course pair prevents duplicate registrations when repeat attempts are not allowed.')],
 {title:'Student and course enrolment',problem:'Explain where Mark belongs and the participation at each end.',solution:'Mark describes a particular student’s enrolment in a particular course, so it belongs to Enrolment. A student may have 0..many enrolments; a course may have 0..many enrolments. Every enrolment has exactly 1 student and exactly 1 course. This resolves the original many-to-many association.'},
 T('Can StudentID alone be the key of Enrolment if a student takes several courses? Explain and propose a key.','Test two course rows for the same student.','No. StudentID repeats. Use the composite key (StudentID, CourseID), or an EnrolmentID primary key with UNIQUE(StudentID, CourseID). If repeated attempts are allowed, add an attempt/period rule to the key or unique constraint.'),
 [Q('A many-to-many relationship is implemented with:',['An associative table','One comma-separated column','No foreign keys'],0,'The associative table stores one row for each permitted pair.'),Q('0..* means:',['Exactly one','Zero or many','Exactly zero'],1,'The minimum is zero; the maximum is many.')], 'college'),
L('big-data',2,'Relational models and big data',[
 S('Relational features','A relation is represented as a table of rows and columns. A column has an intended domain and each row represents one instance of the table’s subject. Keys identify rows and foreign keys connect relations. Row order is not meaningful without ORDER BY. Logical independence helps users work with data without knowing every storage detail.'),
 S('What makes data “big”?','Big data refers to data whose scale, speed, diversity or processing demands require approaches beyond a particular conventional setup. Volume concerns amount, velocity the arrival and processing rate, and variety the forms. Veracity concerns trust and quality; value concerns useful outcomes. These characteristics are a guide, not a fixed size threshold.'),
 S('Choose architecture from the need','Examples include click streams, sensor readings and mixed-format documents. Relational systems still matter and can participate in large-data architectures. Distributed processing and non-relational stores may help some workloads, but introduce operational and consistency trade-offs. More data does not automatically produce better information.')],
 {title:'Sensor readings',problem:'A network sends temperature readings every second, plus technician notes and images. Identify three big-data characteristics.',solution:'Volume: readings accumulate across devices and time. Velocity: new readings arrive continuously and may need rapid processing. Variety: numeric readings, free text and images differ in structure. Device calibration and missing readings also raise veracity questions.'},
 T('Explain why a 20-row table is not automatically “big data”, and why data quality still matters in a large dataset.','Relate the workload to the available tools.','Twenty rows can usually be handled conventionally; big data concerns scale and processing demands relative to the setup. Incorrect or biased records can produce incorrect conclusions even when there are millions of rows.'),
 [Q('Velocity concerns:',['Rate of arrival and processing','Number of columns only','Font size'],0,'A fast incoming stream creates timeliness and processing demands.'),Q('Big data makes relational databases irrelevant.',['True','False'],1,'Relational systems remain useful, including in larger architectures.')]),
L('keys',3,'Tables, keys and referential integrity',[
 S('A database contains tables','A database can contain multiple related tables, views, indexes and other objects. A table holds rows about one subject. A candidate key is a minimal set of attributes that uniquely identifies a row. One candidate key is chosen as the primary key; the others are alternate keys. A composite key has more than one attribute.'),
 S('Primary, secondary and foreign keys','A primary key is unique and not NULL. A foreign key references a candidate key, commonly another table’s primary key, and enforces referential integrity. A nullable foreign key may represent optional participation. In this course, secondary key means a search/retrieval attribute that need not be unique, such as City; terminology can differ between textbooks. Do not confuse a secondary search key with an alternate candidate key.'),
 S('Constraints implement rules','NOT NULL requires a value, UNIQUE prevents duplicate key values, CHECK restricts values and FOREIGN KEY checks references. An index supports access paths; it is not itself a substitute for every integrity rule. Decide what should happen when a referenced row is changed or deleted. CASCADE is a design decision, not a default recommendation.')],
 {title:'Keys in the college demo',problem:'Choose keys for Students and Enrolments and a useful secondary search key.',solution:'Students.StudentID is the primary key. Enrolments.EnrolmentID is its primary key. Enrolments.StudentID and CourseID are foreign keys. UNIQUE(StudentID, CourseID) implements the chosen no-repeat rule. Students.City is a possible non-unique secondary search key; many students may live in the same city.'},
 T('A registration row references StudentID 999, which is absent from Students. Which rule is violated? Is City a suitable primary key?','Distinguish a missing reference from duplicate identification.','The foreign key/referential-integrity rule is violated. City is not a suitable primary key because multiple students can share a city and it can change. Use a stable unique identifier.'),
 [Q('A primary key may contain NULL.',['True','False'],1,'A primary key uniquely identifies every row and cannot be NULL.'),Q('A secondary search key must always be unique.',['True','False'],1,'A search attribute such as City may match many rows.')], 'college','all'),
L('redundancy-erd',3,'Redundancy and revising a relational ERD',[
 S('Redundancy versus necessary references','Storing the same independent fact in several places can lead to anomalies. Repeating CourseName on every enrolment duplicates a course fact. Repeating CourseID as a foreign key is a deliberate relationship, not the same kind of uncontrolled duplication. Some deliberate redundancy is justified later, but it needs a consistency strategy.'),
 S('Create the relational design','Identify subjects, choose keys, place attributes with the subject they describe, and resolve many-to-many relationships. Add foreign keys on the many side of one-to-many relationships. A conceptual relationship is not implemented merely by drawing a line; the relational schema needs the right constraints.'),
 S('Revise when a rule changes','Suppose a student may repeat a course in another semester. UNIQUE(StudentID, CourseID) now rejects valid history. Add a meaningful offering, semester or attempt identifier and revise the unique constraint accordingly. Update the ERD, schema, tests and queries together. Existing data must be migrated deliberately.')],
 {title:'Retaining repeated attempts',problem:'A student takes Databases in semester 1 and repeats it in semester 2. How should the design change?',solution:'One option is CourseOffering(OfferingID, CourseID, Semester, AcademicYear) and Enrolment(EnrolmentID, StudentID, OfferingID, Mark), with UNIQUE(StudentID, OfferingID). Course identifies the subject; CourseOffering identifies a particular delivery. Confirm whether multiple attempts within one offering are allowed before fixing the rule.'},
 T('A Sales table repeats CustomerName and current CustomerAddress in every sale. Explain an anomaly and propose a revised ERD. State an exception for history.','Ask whether the address means current address or delivery address at the time of sale.','Use Customer(CustomerID, CustomerName, CurrentAddress) and Sale(SaleID, CustomerID, ...). Updating one current address avoids conflicting copies. A historical delivery address may be stored separately on a sale intentionally because it is a different fact: the address used for that sale.'),
 [Q('Which repetition is normally necessary?',['A foreign key on each child row','A current course name copied everywhere','The same student profile in every table'],0,'Foreign keys record the relationships between rows.'),Q('When business rules change, update:',['Only a diagram title','The model, constraints and dependent queries','Nothing'],1,'An implementable design and its use must stay consistent.')], 'college'),
L('attributes',4,'Entities, attributes and participation',[
 S('Choose attributes carefully','A simple attribute is treated as indivisible for the model’s purpose. A composite attribute has meaningful parts, such as an address. A multivalued attribute has several values for one entity, such as phone numbers, and is usually represented in a related table. A derived attribute can be calculated, such as age from birth date. Whether a value is simple depends on the required operations.'),
 S('Strong and weak entities','A strong entity has its own identifying key. A weak entity depends on an owner for identification, commonly using the owner key plus a partial key. OrderLine may use (OrderID, LineNumber). Existence dependency and identification dependency are related but different: a child can require a parent while still having an independent surrogate identifier.'),
 S('Participation is a business rule','Mandatory participation means an entity instance must participate in a relationship; optional participation allows zero. A NOT NULL foreign key enforces a required parent for each child. It does not by itself enforce that every parent has at least one child. Some minimum-child rules require application logic, deferred checks or other DBMS-specific mechanisms.')],
 {title:'Phone numbers and order lines',problem:'Model several student phone numbers and identify a line within an order.',solution:'Use StudentPhone(StudentID, PhoneNumber, PhoneType), with an agreed key such as (StudentID, PhoneNumber). Do not store comma-separated numbers. Use OrderLine(OrderID, LineNumber, ProductID, Quantity), keyed by (OrderID, LineNumber), when line numbers only identify lines within their order.'},
 T('Which is safer to store for a person: age or date of birth? Explain. What happens if a child FK is NOT NULL?', 'Consider how time changes a derived value.','Store date of birth when it is required and appropriate; derive age for the relevant date, rather than storing an age that goes stale. A NOT NULL FK requires each child to reference a parent; it does not require every parent to have a child.'),
 [Q('A multivalued phone attribute is usually represented as:',['A related phone table','A comma-separated string','The primary key of every other table'],0,'Separate rows preserve individual values and allow constraints.'),Q('A NOT NULL child FK ensures every parent has a child.',['True','False'],1,'It enforces the child-to-parent requirement, not the reverse.')]),
L('relationship-degree',4,'Unary, binary and ternary relationships',[
 S('Degree is not cardinality','Relationship degree counts participating entity types or roles. A unary relationship relates an entity type to itself, such as Employee supervises Employee. A binary relationship involves two entity types, such as Customer places Order. A ternary relationship involves three, such as Supplier supplies Part to Project. One-to-many describes cardinality, not degree.'),
 S('Self-referencing relationships','For Employee supervision, SupervisorID can reference EmployeeID in the same table. It may be NULL for a top-level employee. The FK checks existence but does not alone prevent a cycle such as A supervises B and B supervises A. Cycle prevention is an additional business rule.'),
 S('Do not lose the triple','A supply agreement can depend on a particular supplier, part and project together. Splitting a ternary fact into three unrelated binary tables can imply combinations that never existed. Use an associative relation containing the relevant foreign keys and attributes such as agreed quantity. Derive its key from the actual uniqueness rules, not from the word ternary.')],
 {title:'Supplier, part and project',problem:'Supplier A supplies Part X to Project 1, while Supplier B supplies X to Project 2. Where is Quantity stored?',solution:'Use Supply(SupplierID, PartID, ProjectID, Quantity) when the quantity describes a triple. A possible key is all three IDs if exactly one aggregate supply row is allowed per triple. Separate deliveries require a DeliveryID or date/sequence rule instead.'},
 T('Classify Employee supervises Employee, Student enrols in Course, and Supplier supplies Part to Project. Is “one-to-many” a degree?', 'Count participating types/roles, then describe counts separately.','They are unary, binary and ternary respectively. One-to-many is cardinality. For a unary supervisor relationship, SupervisorID is a self-referencing FK and a separate rule must prevent invalid cycles.'),
 [Q('One-to-many describes:',['Degree','Cardinality','A column type'],1,'Degree counts participating entity types; cardinality describes instance counts.'),Q('A ternary relationship always decomposes safely into binary pairs.',['True','False'],1,'The individual triple may carry meaning that pairs cannot preserve.')]),
L('erd-review',4,'Develop and review a complete ERD',[
 S('From narrative to diagram','Read the scenario, identify candidate entities and attributes, and write business rules in both directions. Choose keys, add cardinality and optionality, then resolve many-to-many relationships. Validate with example instances. Remove attributes that describe another subject or a relationship rather than the entity they are attached to.'),
 S('A review checklist','Can every row be identified? Does every FK reference an eligible key? Are optional values deliberate? Are repeated facts and multivalued attributes addressed? Can the design store required history? Can each required report be produced without inventing a relationship? Are uniqueness and deletion rules explicit? Explain any rule the DBMS cannot enforce through simple constraints.'),
 S('Revise with evidence','Try an entity with no children, several children, duplicate names, a repeated transaction and a deleted parent. If the model cannot represent a valid case, revise it. If it accepts an invalid case, add or document an enforcement rule. A polished diagram can still encode the wrong requirements.')],
 {title:'Review the college ERD',problem:'Check the Students, Courses and Enrolments design against its rules.',solution:'All three tables have primary keys. Enrolments has two NOT NULL FKs and a unique student-course pair. Mark allows NULL until graded and CHECK restricts a supplied mark to 0-100. Students and courses may exist without enrolments. The current demo excludes repeat attempts; a real system requiring them needs offerings or attempt history.'},
 T('A proposed ERD stores Course1, Course2 and Course3 on Student. Give two problems and replace it with a relational design.','What happens when a student takes a fourth course?', 'The fixed columns limit the number of courses and require repeated logic for queries. Use Student, Course and Enrolment with keys and FKs. One Enrolment row represents each chosen student-course association. Add a period rule if repeat attempts are needed.'),
 [Q('Which is a useful review test?',['Only whether colours match','Whether a valid repeated enrolment can be represented','Whether all names are short'],1,'Example cases test whether the rules are modelled correctly.'),Q('A many-to-many relationship can store its attributes in:',['An associative entity','An arbitrary parent column','The diagram title'],0,'The associative row represents the relationship instance.')], 'college'),
L('normalisation-intro',5,'Anomalies and functional dependencies',[
 S('What normalisation does','Normalisation organises relations using dependencies to reduce update, insertion and deletion anomalies. It is not simply removing every repeated value. A well-designed FK repeats to represent a relationship. First state the meaning of each row, the candidate keys and the business rules that determine dependencies.'),
 S('Functional dependency','X → Y means that if two rows have the same X value, they must have the same Y value under the stated rules. X is a determinant. The dependency is a rule about all valid data, not a pattern inferred from two sample rows. A candidate key determines all attributes and is minimal. A full dependency needs the entire composite determinant; a partial dependency needs only a proper subset.'),
 S('One order-line relation','Assume OrderLine(OrderID, ProductID, OrderDate, CustomerID, CustomerName, ProductName, UnitPrice, Quantity), key (OrderID, ProductID), one product line per order, one customer per order, and one catalogue price per product. Dependencies include OrderID → OrderDate, CustomerID; CustomerID → CustomerName; ProductID → ProductName, UnitPrice; and (OrderID, ProductID) → Quantity. If a price is captured per sale instead, its dependency changes.')],
 {title:'Three anomalies',problem:'ProductName is repeated across order lines. Explain update, insertion and deletion anomalies.',solution:'Update: renaming a product requires changing many rows and some copies may disagree. Insertion: without an order, a design keyed only by order lines may have no valid place to record a new product. Deletion: removing the last line for a product may accidentally remove its only description. Separate product facts from order-line facts.'},
 T('Does seeing the same ProductID with one ProductName in a small sample prove ProductID → ProductName? Explain.', 'Dependencies come from rules, not coincidence.','No. The organisation must define that each product ID has one product name at the relevant time. A small sample may fail to show a valid exception. Historical product names need a time-aware model.'),
 [Q('X → Y means:',['One X value determines one Y value','X is numerically larger than Y','Y is always a primary key'],0,'Equal X values must imply equal Y values in valid data.'),Q('Normalisation removes every repeated FK.',['True','False'],1,'Foreign keys deliberately repeat to record associations.')], 'dependencies'),
L('first-second-nf',5,'First and second normal form',[
 S('First normal form (1NF)','Use one value from the intended domain at each row-column intersection and remove repeating groups. Replace an order containing a list of products with one row per order-product association. Choose a candidate key and describe what one row means. Atomicity depends on the domain and operations: do not split a value merely because it contains multiple characters.'),
 S('Second normal form (2NF)','A relation is in 2NF when it is in 1NF and no non-prime attribute depends on a proper subset of any candidate key. A non-prime attribute is one not contained in any candidate key. In our worked example, the relevant candidate key is (OrderID, ProductID). OrderDate and CustomerID depend on OrderID alone; ProductName and UnitPrice depend on ProductID alone. These are partial dependencies.'),
 S('Decompose without losing the association','Create Orders(OrderID, OrderDate, CustomerID, CustomerName), Products(ProductID, ProductName, UnitPrice), and OrderLines(OrderID, ProductID, Quantity). The line key is still the pair, and its two FKs preserve the association. CustomerName remains dependent through CustomerID in Orders, so this 2NF result is not yet 3NF. A single-attribute candidate key has no proper nonempty subset, but check other candidate keys as well.')],
 {title:'1NF to 2NF',problem:'Order 101 has product 7 quantity 2 and product 8 quantity 1. Remove partial dependencies.',solution:'1NF contains two line rows keyed by (101,7) and (101,8), with repeated order facts. In 2NF, Orders stores one row for order 101, Products stores one row per product, and OrderLines stores (101,7,2) and (101,8,1). Joining through OrderID and ProductID reconstructs the order details. Do not discard either FK.'},
 T('Enrolment(StudentID, CourseID, StudentName, CourseName, Mark) has key (StudentID, CourseID). Assume each ID determines its corresponding name. Produce 2NF tables.', 'Mark belongs to the pair. Each name belongs to one side.','Student(StudentID PK, StudentName), Course(CourseID PK, CourseName), Enrolment(StudentID PK/FK, CourseID PK/FK, Mark). StudentID → StudentName and CourseID → CourseName were partial dependencies. The pair determines Mark.'),
 [Q('A partial dependency involves:',['A proper subset of a candidate key','An arbitrary NULL','A name that is too long'],0,'It matters when a non-prime attribute depends on only part of a candidate key.'),Q('Which stays in OrderLines?',['Quantity for the order-product pair','Only ProductName','Only CustomerName'],0,'Quantity describes the relationship instance.')], 'normalisation'),
L('third-nf',5,'Third normal form and design trade-offs',[
 S('Third normal form (3NF)','Formally, for every non-trivial functional dependency X → A, either X is a superkey or A is prime. A superkey uniquely identifies a row but may include unnecessary attributes; a prime attribute belongs to some candidate key. In the common single-key examples here, 3NF removes transitive dependencies of non-key attributes on the key through another non-key determinant.'),
 S('Finish the worked example','In Orders(OrderID, OrderDate, CustomerID, CustomerName), OrderID determines CustomerID and CustomerID determines CustomerName. Move CustomerName into Customers(CustomerID, CustomerName). Keep CustomerID in Orders as an FK. The final tables are Customers, Orders, Products and OrderLines. Each independent fact now has a clearer home.'),
 S('Normalisation supports the whole design','Aim for lossless reconstruction of valid facts and constraints that can still be enforced. Do not split tables randomly or invent dependencies. Normalisation and ER modelling complement one another: revisit the model when new dependencies or historical requirements emerge. Deliberate denormalisation can serve a measured performance need later, but requires documented consistency controls and does not replace sound initial design.')],
 {title:'The 3NF result',problem:'List all final tables, keys and important dependencies for the order-line scenario.',solution:'Customers(CustomerID PK, CustomerName); Orders(OrderID PK, OrderDate, CustomerID FK); Products(ProductID PK, ProductName, UnitPrice); OrderLines(OrderID PK/FK, ProductID PK/FK, Quantity). CustomerID → CustomerName; OrderID → OrderDate, CustomerID; ProductID → ProductName, UnitPrice; (OrderID,ProductID) → Quantity. These depend on the stated catalogue-price and no-duplicate-line assumptions.'},
 T('Employee(EmployeeID, DepartmentID, DepartmentName) has EmployeeID as key and DepartmentID → DepartmentName. Decompose to 3NF and explain the transitive dependency.', 'Keep DepartmentID as an FK on Employee.','Department(DepartmentID PK, DepartmentName) and Employee(EmployeeID PK, DepartmentID FK). EmployeeID → DepartmentID → DepartmentName was transitive; DepartmentName belongs to Department. Joining by DepartmentID reconstructs the information.'),
 [Q('What must remain on Orders after moving customer details?',['CustomerID as a foreign key','A list of all customer names','No customer reference'],0,'The FK preserves which customer placed the order.'),Q('Which justifies denormalisation?',['A measured requirement and consistency plan','Avoiding all keys','A preference for one giant table'],0,'It should be deliberate and based on evidence.')], 'normalisation'),
L('sql-foundations',6,'SQL dialects, SELECT and filtering',[
 S('SQL is a language, not a DBMS','SQL describes operations on relational data. SQL Server, PostgreSQL and MySQL implement SQL with different extensions and details. Data definition language includes CREATE, ALTER and DROP. Data manipulation includes INSERT, UPDATE and DELETE; SELECT retrieves rows and is sometimes taught separately as DQL. Use the terminology required by your course while understanding the operation.'),
 S('Read and filter rows','SELECT chooses expressions or columns, FROM identifies a source, WHERE filters rows and ORDER BY defines result order. Use AND, OR, NOT and parentheses to make Boolean logic clear. Single quotes delimit string literals. IS NULL tests for missing values; = NULL does not behave like equality with a normal value. NULL means unknown or absent according to the column’s meaning, not automatically zero.'),
 S('Important dialect differences','SQL Server uses TOP (n) to limit a simple SELECT, while PostgreSQL and MySQL commonly use LIMIT n. Identity-generation syntax, string concatenation, date functions and identifier quoting also differ. In StudyLab, select a dialect for examples and the documented compatibility checks. The execution engine is local SQLite, not any of these three servers; it does not reproduce every type, collation or function.')],
 {title:'First five students',problem:'Return the first five student IDs and names in ID order.',solution:'SQL Server: SELECT TOP (5) StudentID, StudentName FROM Students ORDER BY StudentID; PostgreSQL/MySQL: SELECT StudentID, StudentName FROM Students ORDER BY StudentID LIMIT 5; The college demo returns Lebo, Thabo, Naledi, Peter and Maria in that order. Without ORDER BY, the chosen first rows are not a dependable order.'},
 T('Return students from Polokwane aged at least 21, sorted by name. Explain why parentheses matter when adding OR conditions.', 'Use WHERE with AND, then ORDER BY.','SELECT StudentName, Age FROM Students WHERE City = \'Polokwane\' AND Age >= 21 ORDER BY StudentName; For multiple cities, group them: (City = \'Polokwane\' OR City = \'Pretoria\') AND Age >= 21. Otherwise operator precedence may change which rows satisfy the age rule.'),
 [Q('How do you test a missing mark?',['Mark = NULL','Mark IS NULL','Mark = 0 always'],1,'IS NULL tests missingness; equality with NULL is not a normal true/false comparison.'),Q('SQL Server’s row-limit syntax is:',['TOP (5)','LIMIT 5 only','A comma-separated list'],0,'TOP is used in the SQL Server SELECT form taught here.')],null,'top'),
L('sql-ddl',6,'Create tables, views and indexes',[
 S('Declare columns and constraints','CREATE TABLE names columns and their intended types. Select types for the values and required precision. INTEGER is for whole numbers, DECIMAL(p,s) for exact scaled numeric values in native systems, VARCHAR(n) for variable text, and DATE for dates. PRIMARY KEY, FOREIGN KEY, NOT NULL, UNIQUE and CHECK represent different rules. The browser SQLite engine has different type-affinity rules: it does not enforce every native length, precision or date rule.'),
 S('Views and indexes serve different purposes','A view names a stored SELECT definition and can simplify access or present a subset of data. An ordinary view is not automatically a materialised snapshot. An index is an additional access structure that can improve some queries; it also consumes space and makes writes more expensive. An optimiser decides whether an index is useful. An index is not a guarantee of row order.'),
 S('DDL differs between products','DROP INDEX syntax differs: SQL Server and MySQL use DROP INDEX index_name ON table_name; PostgreSQL uses DROP INDEX index_name. Generated identifiers also differ. The browser lab uses explicit integer keys and supports portable CREATE TABLE, CREATE VIEW and CREATE INDEX statements, plus the documented DROP INDEX adaptation. Use native tools for server administration and advanced DDL.')],
 {title:'A safe study-group table',problem:'Create a group with a positive capacity and a unique name.',solution:'CREATE TABLE StudyGroups (GroupID INTEGER PRIMARY KEY, GroupName VARCHAR(60) NOT NULL UNIQUE, Capacity INTEGER NOT NULL CHECK (Capacity > 0)); INSERT INTO StudyGroups VALUES (1, \'SQL study circle\', 12); The CHECK rejects zero or negative capacity; NOT NULL prevents an absent capacity. VARCHAR length enforcement must also be tested in the native DBMS.'},
 T('Explain a view versus an index, then write SQL for a view of passing enrolments.', 'One defines a query; the other supports access paths.','A view stores a query definition; an index supports access paths and costs write/storage work. CREATE VIEW PassingMarks AS SELECT StudentID, CourseID, Mark FROM Enrolments WHERE Mark >= 50; SELECT * FROM PassingMarks; An ordinary view reflects the underlying data when queried.'),
 [Q('Which constraint rejects missing values?',['NOT NULL','ORDER BY','AVG'],0,'NOT NULL is a column-value requirement.'),Q('An ordinary view is always a copied snapshot.',['True','False'],1,'An ordinary view represents a query over its sources.')],null,'table'),
L('sql-dml',6,'INSERT, UPDATE, DELETE and transactions',[
 S('Change rows deliberately','INSERT adds rows, UPDATE changes matching rows and DELETE removes matching rows. State column names in INSERT so the intended mapping is clear. Use a SELECT with the planned WHERE clause before a change when checking which rows will be affected. An UPDATE or DELETE without WHERE normally affects all rows, not just the one you were thinking about.'),
 S('Respect integrity','A duplicate primary key or a missing referenced parent should fail. Deleting a parent with children may be restricted or cascade according to the design. Check the defined rule before deletion. Use an explicit transaction in native tools when related changes must succeed or fail together. COMMIT makes a transaction permanent; ROLLBACK discards uncommitted changes.'),
 S('How the browser sandbox behaves','Each Run in StudyLab is wrapped as a batch: if one statement fails, changes from that run are rolled back. Previous successful runs remain in that open workspace. Transaction-control statements are not supported in the browser lab. Stop or a query timeout restarts the worker and reloads the demo. Draft SQL is saved; database changes themselves are not persisted after reload or leaving the workspace.')],
 {title:'Add, edit and remove one fictional row',problem:'Work on StudentID 21 only.',solution:'INSERT INTO Students (StudentID, StudentName, City, Age) VALUES (21, \'Demo Learner\', \'Polokwane\', 22); UPDATE Students SET Age = 23 WHERE StudentID = 21; SELECT * FROM Students WHERE StudentID = 21; DELETE FROM Students WHERE StudentID = 21; The SELECT displays age 23; the final DELETE restores the original 20-student dataset.'},
 T('A student writes DELETE FROM Students; while intending to remove ID 21. Identify the risk and correct it.', 'Which rows match a statement without WHERE?', 'Without WHERE, all student rows are targeted, subject to constraints. Correct statement: DELETE FROM Students WHERE StudentID = 21; First inspect SELECT * FROM Students WHERE StudentID = 21; and confirm that the identifier is the intended record.'),
 [Q('UPDATE without WHERE normally targets:',['All rows','Only the first row','No rows'],0,'A WHERE clause restricts the update.'),Q('What happens if a StudyLab batch fails halfway through?',['Its changes are rolled back','Half is always kept','Every previous run is erased'],0,'The failed run is atomic; prior successful runs remain.')],null,'crud'),
L('sql-aggregate',6,'Joins, aggregates, GROUP BY and HAVING',[
 S('Combine related rows','JOIN matches rows using a stated condition. INNER JOIN returns matches. LEFT JOIN keeps every row from the left source and supplies NULL for missing right-side values. Join on the actual key relationship, not equal-looking names. A missing join condition can multiply rows and inflate totals. Multiple child matches legitimately produce multiple result rows.'),
 S('Aggregate functions and NULL','COUNT(*) counts rows; COUNT(column) counts non-NULL values in that column. SUM, AVG, MIN and MAX summarise non-NULL values. AVG of marks 50, NULL and 100 is 75, not 50. Most aggregates return NULL for an empty set, while COUNT returns zero. Use COALESCE when the intended report explicitly needs a replacement for NULL.'),
 S('Group before filtering aggregates','WHERE filters input rows. GROUP BY defines groups; non-aggregated selected columns should be grouped appropriately. HAVING filters groups using aggregate conditions. ORDER BY sorts the final result. COUNT after a join counts joined rows, which may not equal the number of students. For a LEFT JOIN count a non-NULL child key to count actual children rather than the preserved parent row.')],
 {title:'Course averages',problem:'Show courses with average marks at least 60.',solution:'SELECT c.CourseName, COUNT(*) AS EnrolmentCount, ROUND(AVG(e.Mark), 2) AS AverageMark FROM Courses AS c JOIN Enrolments AS e ON e.CourseID = c.CourseID GROUP BY c.CourseID, c.CourseName HAVING AVG(e.Mark) >= 60 ORDER BY AverageMark DESC; AVG ignores unmarked enrolments. COUNT(*) still includes those rows. Explain both denominators.'},
 T('Marks are 60, NULL and 90. Give COUNT(*), COUNT(Mark), SUM(Mark), AVG(Mark), MIN(Mark) and MAX(Mark).', 'NULL is ignored by the column aggregate functions.', 'COUNT(*) = 3; COUNT(Mark) = 2; SUM = 150; AVG = 75; MIN = 60; MAX = 90. Do not convert the unknown mark to zero unless that is an explicit reporting rule.'),
 [Q('HAVING is used to filter:',['Groups after aggregation','Column names before parsing','Only indexes'],0,'HAVING applies group-level conditions.'),Q('AVG of 60, NULL and 90 is:',['50','75','150'],1,'Only the two supplied marks are averaged.')], 'college','group')
];

const unitPractice=[
  [
    [
      "Compare database users",
      "A college has a lecturer entering marks, a developer building the portal and a DBA restoring a backup. Explain each responsibility.",
      "The lecturer is an end user responsible for accurate authorised entry. The developer implements the interface and queries. The DBA maintains recoverability and performs a tested restore. Permissions should reflect each role."
    ],
    [
      "Plan a database",
      "A shop keeps conflicting customer phone numbers in three spreadsheets. Propose a database plan and two migration checks.",
      "Create Customers with a stable key, plus Orders with a customer foreign key. Define which phone number is authoritative and resolve duplicates before import. Check customer counts and that each order references an existing customer after migration."
    ],
    [
      "Evaluate costs",
      "Give two costs of replacing shared spreadsheets with a managed database, and explain why a backup alone is not a recovery plan.",
      "Costs include schema and migration work, training, hosting or licences, and administration. A backup must be restorable within the required time; test restores, document procedures and protect backup access."
    ]
  ],
  [
    [
      "Read cardinality",
      "State the cardinalities when each ticket has one requester and each requester may create many tickets.",
      "Requester 1 to Ticket 0..many. Ticket.RequesterID is a required foreign key. A requester can exist before creating a ticket, while every ticket must have exactly one existing requester."
    ],
    [
      "Model optional participation",
      "A ticket may be unassigned or assigned to one technician; each technician may have many tickets. Name the FK and nullability.",
      "Tickets.AssignedToID is a nullable foreign key to Technicians.TechnicianID. A NULL denotes unassigned. Each ticket has zero or one technician and each technician zero or many tickets."
    ],
    [
      "Choose attribute types",
      "Classify a person name, date of birth, age and multiple phone numbers. Explain a suitable relational design.",
      "A name can be composite in a conceptual model; date of birth is stored; age is derived for a reference date. Phone numbers are multivalued and belong in PersonPhones with a foreign key, rather than a comma-separated field."
    ]
  ],
  [
    [
      "Choose candidate keys",
      "A student has StudentID, an institutionally unique StudentNumber, Name and City. Identify candidate, primary and secondary/search keys.",
      "StudentID and StudentNumber are candidate keys if each is unique and minimal. Choose StudentID as primary and enforce StudentNumber as UNIQUE NOT NULL. Name or City can be search keys but are not reliable row identifiers."
    ],
    [
      "Locate a foreign key",
      "An order belongs to one customer. Explain why the customer key belongs in Orders rather than storing a list of order IDs in Customers.",
      "Orders.CustomerID is the foreign key on the many side. It permits many order rows per customer without repeating groups. A customer may have zero orders; each required customer reference must match an existing customer."
    ],
    [
      "Revise an ERD",
      "An employee previously belonged to one project. The new rule allows many projects per employee and many employees per project. Show the revision.",
      "Introduce EmployeeProjects(EmployeeID PK/FK,ProjectID PK/FK) and remove the single ProjectID from Employees after migration. Add allocation details to the bridge if they depend on that employee-project pair."
    ]
  ],
  [
    [
      "Unary relationships",
      "Model an employee supervised by at most one other employee, and prevent self-supervision conceptually.",
      "Employees has nullable SupervisorID referencing Employees.EmployeeID. One supervisor can supervise many employees. CHECK(SupervisorID<>EmployeeID) prevents direct self-supervision; longer management cycles need additional validation."
    ],
    [
      "Ternary relationships",
      "A supplier supplies a product to a project with an agreed quantity. Explain why three separate pairwise relationships may lose meaning.",
      "The fact depends on all three identities together. Use Supply(SupplierID,ProductID,ProjectID,Quantity) with foreign keys and a suitable composite key. Separate pairs cannot prove which supplier delivered which product to a particular project."
    ],
    [
      "Review business rules",
      "A library book title can have many physical copies. Each copy can have many historical loans but at most one current loan. Propose entities and an enforcement note.",
      "Use Titles, Copies, Members and Loans; Copies references Titles and Loans references Copies and Members. A current-loan uniqueness rule needs a filtered unique index or controlled transaction logic, not simply a one-to-many ERD line."
    ]
  ],
  [
    [
      "Partial dependencies",
      "Normalise Line(OrderID,ProductID,OrderDate,ProductName,Quantity) assuming one line per product per order.",
      "Key is (OrderID,ProductID). OrderID determines OrderDate; ProductID determines ProductName; the whole key determines Quantity. 2NF: Orders(OrderID PK,OrderDate), Products(ProductID PK,ProductName), Lines(OrderID PK/FK,ProductID PK/FK,Quantity)."
    ],
    [
      "Transitive dependencies",
      "Normalise Employee(EmployeeID,EmployeeName,DepartmentID,DepartmentName) when each department has one name.",
      "EmployeeID determines EmployeeName and DepartmentID; DepartmentID determines DepartmentName. Create Departments(DepartmentID PK,DepartmentName) and Employees(EmployeeID PK,EmployeeName,DepartmentID FK). This removes the non-key transitive dependency."
    ],
    [
      "State assumptions",
      "Does a table with a single-column primary key automatically satisfy 3NF? Explain with an example.",
      "No. It may avoid partial dependency on that selected key, but can still have transitive dependencies, such as EmployeeID -> DepartmentID -> DepartmentName. Other candidate keys must also be considered when determining normal forms."
    ]
  ],
  [
    [
      "NULL aggregates",
      "For marks 40, NULL and 80 calculate COUNT(*), COUNT(Mark), AVG(Mark) and SUM(Mark). Explain the integer-average issue in SQL Server.",
      "COUNT(*)=3, COUNT(Mark)=2, SUM=120 and the mathematical average is 60. SQL Server AVG of integer input returns an integer type; use AVG(CAST(Mark AS DECIMAL(10,2))) when a fractional average is needed."
    ],
    [
      "Filtering groups",
      "Write SQL listing CourseID and average Mark for courses with at least five non-NULL marks, averaging only marks >=50.",
      "SELECT CourseID,AVG(CAST(Mark AS DECIMAL(10,2))) AS AverageMark FROM Enrolments WHERE Mark>=50 GROUP BY CourseID HAVING COUNT(Mark)>=5; WHERE removes failing and NULL rows before groups are counted."
    ],
    [
      "Safe changes",
      "You need to delete one test student. Give a safe sequence and explain the role of foreign keys.",
      "Preview SELECT with the exact StudentID, check enrolments and other dependants, use a controlled practice transaction and DELETE with that predicate, verify affected rows, then commit or roll back. A foreign key may reject deleting a referenced student; do not disable integrity just to force the delete."
    ]
  ]
];
for (const lesson of dbLessons) { lesson.tasks=[lesson.task,...unitPractice[lesson.unit-1].map(([title,prompt,solution])=>({title,prompt,hint:"Identify the business rule, key and relevant SQL or design concept before writing your answer.",solution}))]; }
